-- Windows Rules https://wiki.hyprland.org/Configuring/Window-Rules/ #

-- Float Necessary Windows
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

require("config.colours")


hl.window_rule({
    match = {
        focus = true,
    },
    border_color = mauve,
})

hl.window_rule({
    match = {
        focus = false,
    },
    border_color = crust,   
})

hl.window_rule({
    match = {
        class = "^(org.pulseaudio.pavucontrol)",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^()$",
        title = "^(Picture in picture)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^()$",
        title = "^(Save File)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^()$",
        title = "^(Open File)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(LibreWolf)$",
        title = "^(Picture-in-Picture)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(blueman-manager)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(xdg-desktop-portal-gtk|xdg-desktop-portal-kde|xdg-desktop-portal-hyprland)(.*)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(polkit-gnome-authentication-agent-1|hyprpolkitagent|org.org.kde.polkit-kde-authentication-agent-1)(.*)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(CachyOSHello)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(zenity)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^()$",
        title = "^(Steam - Self Updater)$",
    },
    float = true,
})

-- Increase the opacity
hl.window_rule({
    match = {
        class = "^(thunar|nemo)$",
    },
    opacity = 0.92,
})

hl.window_rule({
    match = {
        class = "^(discord|armcord|webcord)$",
    },
    opacity = 0.96,
})

hl.window_rule({
    match = {
        title = "^(QQ|Telegram)$",
    },
    opacity = 0.95,
})

hl.window_rule({
    match = {
        title = "^(NetEase Cloud Music Gtk4)$",
    },
    opacity = 0.95,
})

-- General window rules
hl.window_rule({
    match = {
        title = "^(danmufloat)$",
    },
    pin = true,
})

hl.window_rule({
    match = {
        title = "^(danmufloat|termfloat)$",
    },
    rounding = 5,
})

hl.window_rule({
    match = {
        class = "^(kitty|Alacritty)$",
    },
    animation = "slide right",
})

hl.window_rule({
    match = {
        class = "^(org.mozilla.firefox)$",
    },
    no_blur = true,
})


-- Windows Rules End #

-- Workspaces Rules https://wiki.hyprland.org/Configuring/Workspace-Rules/ #
-- workspace = 1, default:true, monitor:$priMon
-- workspace = 6, default:true, monitor:$secMon
-- Workspace selectors https://wiki.hyprland.org/Configuring/Workspace-Rules/#workspace-selectors
-- workspace = r[1-5], monitor:$priMon
-- workspace = r[6-10], monitor:$secMon
-- workspace = special:scratchpad, on-created-empty:$applauncher
-- no_gaps_when_only deprecated instead workspaces rules with selectors can do the same
-- Smart gaps from 0.45.0 https://wiki.hyprland.org/Configuring/Workspace-Rules/#smart-gaps
hl.workspace_rule({
    workspace = "w[tv1-10]",
    gaps_out = 5,
    gaps_in = 3,
})

hl.workspace_rule({
    workspace = "f[1]",
    gaps_out = 5,
    gaps_in = 3,
})

-- Workspaces Rules End #

-- Layers Rules #
hl.layer_rule({
    match = { namespace = "logout_dialog" },
    animation = "slide top",
})

-- layerrule = animation popin 50%, waybar
hl.layer_rule({
    match = { namespace = "waybar" },
    animation = "slide down",
})

hl.layer_rule({
    match = { namespace = "wallpaper" },
    animation = "fade 50%",
})

-- Layers Rules End #
